	@Test
	public void countUsesAggregateWithoutEnumeratingStatements() throws Exception {
		Repository delegate = repeatedQuadStore();
		Repository repository = spy(delegate);
		RepositoryConnection realConnection = delegate.getConnection();
		RepositoryConnection connection = spy(realConnection);
		AtomicReference<TupleQuery> preparedQuery = new AtomicReference<>();
		String encodedObject = Protocol
				.encodeValue(SimpleValueFactory.getInstance().createLiteral("shared \"quoted\"\n", "en"));
		doReturn(connection).when(repository).getConnection();
		doAnswer(invocation -> {
			TupleQuery query = spy(
					realConnection.prepareTupleQuery(invocation.getArgument(0), invocation.getArgument(1)));
			preparedQuery.set(query);
			return query;
		}).when(connection).prepareTupleQuery(any(QueryLanguage.class), anyString());

		List<JsonNode> records = count(repository, "subj", "<urn:test:s>", "pred", "<urn:test:p>", "obj",
				encodedObject);

		assertThat(rows(records)).singleElement()
				.satisfies(row -> assertThat(row.get(0).path("value").asText()).isEqualTo("4"));
		verify(connection, never()).getStatements(any(), any(), any(), anyBoolean(), any(Resource[].class));
		ArgumentCaptor<String> queryText = ArgumentCaptor.forClass(String.class);
		verify(connection).prepareTupleQuery(eq(QueryLanguage.SPARQL), queryText.capture());
		assertThat(queryText.getValue()).contains("COUNT(*)").doesNotContain("urn:test:s", "shared");
		verify(preparedQuery.get()).setIncludeInferred(false);
		verify(preparedQuery.get()).setMaxExecutionTime(BrowseList.COUNT_BUDGET_SECONDS);
		verify(preparedQuery.get()).setBinding("s", SimpleValueFactory.getInstance().createIRI("urn:test:s"));
		verify(preparedQuery.get()).setBinding("p", SimpleValueFactory.getInstance().createIRI("urn:test:p"));
		verify(preparedQuery.get()).setBinding("o",
				SimpleValueFactory.getInstance().createLiteral("shared \"quoted\"\n", "en"));
		verify(preparedQuery.get(), never()).setDataset(any());
	}

