	private static Repository store() {
		Repository repository = new SailRepository(new MemoryStore());
		repository.init();
		ValueFactory vf = repository.getValueFactory();
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(vf.createIRI("urn:test:s"), vf.createIRI("urn:test:p"), vf.createLiteral("one"));
			connection.add(vf.createIRI("urn:test:s"), vf.createIRI("urn:test:p"), vf.createLiteral("two"),
					vf.createIRI("urn:test:g"));
			connection.add(vf.createIRI("urn:test:other"), vf.createIRI("urn:test:p"), vf.createLiteral("three"));
		}
		return repository;
	}

	private static Repository repeatedQuadStore() {
		Repository repository = new SailRepository(new MemoryStore());
		repository.init();
		ValueFactory vf = repository.getValueFactory();
		IRI subject = vf.createIRI("urn:test:s");
		IRI predicate = vf.createIRI("urn:test:p");
		Value object = vf.createLiteral("shared \"quoted\"\n", "en");
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(subject, predicate, object);
			connection.add(subject, predicate, object, vf.createIRI("urn:test:g1"));
			connection.add(subject, predicate, object, vf.createIRI("urn:test:g2"));
			BNode context = vf.createBNode("graph");
			connection.add(subject, predicate, object, context);
			BNode blankSubject = vf.createBNode("subject");
			connection.add(blankSubject, predicate, object);
			connection.add(blankSubject, predicate, object, vf.createIRI("urn:test:g3"));
			connection.add(blankSubject, predicate, object, context);
		}
		return repository;
	}

	private static Repository storeWithSentinelNamedGraph(IRI context) {
		Repository repository = new SailRepository(new MemoryStore());
		repository.init();
		try (RepositoryConnection connection = repository.getConnection()) {
			IRI subject = SimpleValueFactory.getInstance().createIRI("urn:test:s");
			IRI predicate = SimpleValueFactory.getInstance().createIRI("urn:test:p");
			Value object = SimpleValueFactory.getInstance().createLiteral("sentinel");
			connection.add(subject, predicate, object);
			connection.add(subject, predicate, SimpleValueFactory.getInstance().createLiteral("default-only"));
			connection.add(subject, predicate, object, context);
		}
		return repository;
	}

	private static Repository storeWithObject(Value object) {
		Repository repository = new SailRepository(new MemoryStore());
		repository.init();
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(SimpleValueFactory.getInstance().createIRI("urn:test:s"),
					SimpleValueFactory.getInstance().createIRI("urn:test:p"), object);
		}
		return repository;
	}

	private static void assertMalformedAggregateResult(boolean hasRow, Value countValue) throws Exception {
		Repository delegate = store();
		Repository repository = spy(delegate);
		RepositoryConnection connection = spy(delegate.getConnection());
		TupleQuery query = mock(TupleQuery.class);
		TupleQueryResult result = mock(TupleQueryResult.class);
		BindingSet bindings = mock(BindingSet.class);
		when(query.evaluate()).thenReturn(result);
		when(result.hasNext()).thenReturn(hasRow);
		if (hasRow) {
			when(result.next()).thenReturn(bindings);
			when(bindings.getValue("count")).thenReturn(countValue);
		}
		doReturn(connection).when(repository).getConnection();
		doReturn(query).when(connection).prepareTupleQuery(any(QueryLanguage.class), anyString());

		assertThatThrownBy(() -> count(repository)).isInstanceOf(QueryEvaluationException.class);
		verify(result).close();
		verify(connection).close();
	}

	private static List<JsonNode> count(Repository repository, String... parameters) throws Exception {
		return count(repository, new MockHttpServletResponse(), parameters);
	}

	private static List<JsonNode> count(Repository repository, MockHttpServletResponse response, String... parameters)
			throws Exception {
		String[] withCount = new String[parameters.length + 2];
		withCount[0] = "count";
		withCount[1] = "true";
		System.arraycopy(parameters, 0, withCount, 2, parameters.length);
		return request(repository, response, withCount);
	}

	private static List<JsonNode> preview(Repository repository, MockHttpServletResponse response,
			String... parameters) throws Exception {
		String[] withPreview = new String[parameters.length + 2];
		withPreview[0] = "preview";
		withPreview[1] = "true";
		System.arraycopy(parameters, 0, withPreview, 2, parameters.length);
		return request(repository, response, withPreview);
	}

	private static List<String> vars(List<JsonNode> records) {
		List<String> names = new ArrayList<>();
		records.stream()
				.filter(record -> "vars".equals(record.path("type").asText()))
				.findFirst()
				.orElseThrow()
				.path("values")
				.forEach(name -> names.add(name.asText()));
		return names;
	}

	private static JsonNode metadata(List<JsonNode> records) {
		return records.stream()
				.filter(record -> "metadata".equals(record.path("type").asText()))
				.findFirst()
				.map(record -> record.path("values"))
				.orElse(new ObjectMapper().createObjectNode());
	}

	private static List<JsonNode> request(Repository repository, MockHttpServletResponse response,
			String... parameters) throws Exception {
		RemoveServlet countingServlet = new RemoveServlet();
		countingServlet.setRepository(repository);
		countingServlet.setRepositoryManager(mock(RepositoryManager.class));
		countingServlet.init(TestServletConfig.withParams("remove", "cookie-max-age", "300"));
		try {
			MockHttpServletRequest request = new MockHttpServletRequest("GET", "/remove");
			request.addHeader("Accept", WorkbenchPageProtocol.ACCEPT);
			for (int index = 0; index < parameters.length; index += 2) {
				request.addParameter(parameters[index], parameters[index + 1]);
			}
			countingServlet.service(request, response);
			ObjectMapper mapper = new ObjectMapper();
			return response.getContentAsString().lines().map(line -> {
				try {
					return mapper.readTree(line);
				} catch (Exception e) {
					throw new IllegalStateException(e);
				}
			}).toList();
		} finally {
			countingServlet.destroy();
			repository.shutDown();
		}
	}

	private static final class RemoveServletForTest extends RemoveServlet {
		private final TupleResultBuilder builder;

		private RemoveServletForTest(TupleResultBuilder builder) {
			this.builder = builder;
		}

		@Override
		protected TupleResultBuilder getTupleResultBuilder(HttpServletRequest req, HttpServletResponse resp,
				OutputStream outputStream) {
			return builder;
		}
	}

	private static List<JsonNode> rows(List<JsonNode> records) {
		return records.stream()
				.filter(record -> "rows".equals(record.path("type").asText()))
				.flatMap(record -> {
					List<JsonNode> values = new ArrayList<>();
					record.path("values").forEach(values::add);
					return values.stream();
				})
				.toList();
	}
